/** Everything the markup binds to, for one position in the loop. */
export function values(p) {
  // p is the argument.
  function lin(k) {
    if (p <= k[0][0]) return k[0][1];
    for (var i = 1; i < k.length; i++) if (p <= k[i][0]) { var a = k[i-1], b = k[i], f = (p - a[0]) / (b[0] - a[0]); f = 1 - Math.pow(1 - f, 3); return a[1] + (b[1] - a[1]) * f; }
    return k[k.length-1][1];
  }
  var D = {"rows": [[2400, 0, " m\u00b2"], [9480.0, 0, " m\u00b2"], [10500.0, 0, " m\u00b2"], [3.95, 2, ""], [86, 0, ""], [27.0, 0, " m\u00b2"]]};
  var out = p < 94 ? 1 : Math.max(0, 1 - (p - 94) / 6);
  var ph = [[0,12],[12,28],[28,44],[44,66],[66,80]];
  var v = {};
  for (var i = 0; i < 5; i++) { v['on'+i] = (p >= ph[i][0] && p < ph[i][1]) ? 1 : 0; v['done'+i] = (p >= ph[i][1] && p < 97) ? out : 0; }
  // rules dialog
  v.rulesO = lin([[0,0],[2,1],[10,1],[12,0]]);
  v.rulesT = 'translateY(' + lin([[0,16],[2,0]]).toFixed(1) + 'px)';
  // boundaries draw (pathLength=1)
  var bd = lin([[12,0],[26,1]]);
  v.bndDash = 'stroke-dasharray: 1; stroke-dashoffset: ' + (1 - bd).toFixed(3) + '; opacity: ' + ((bd > 0.002 ? 1 : 0) * out) + ';';
  // classify fills + tags
  var cl = lin([[28,0],[36,1]]);
  v.fillU = lin([[28,0],[33,1]]) * out; v.fillC = lin([[31,0],[36,1]]) * out; v.fillK = lin([[33,0],[38,1]]) * out; v.fillB = lin([[35,0],[40,1]]) * out;
  v.tagO = lin([[36,0],[42,1]]) * out; v.legO = lin([[28,0],[34,1]]) * out;
  // schedule count-up, one row after another
  v.schO = lin([[42,0],[45,1]]) * out;
  D.rows.forEach(function(r, i) {
    var s = 45 + i * 3, f = lin([[s,0],[s+4,1]]);
    var val = r[0] * f;
    var txt = (r[1] ? val.toFixed(r[1]) : Math.round(val).toLocaleString('en-US')) + r[2];
    v['r'+i] = f > 0 ? txt : '—';
    v['c'+i] = (p >= s+4 && p < 97) ? out : 0;
  });
  // export toast
  v.xlO = lin([[68,0],[71,1]]) * out;
  v.xlT = 'translateY(' + lin([[68,14],[71,0]]).toFixed(1) + 'px)';
  return { v: v };}

const card = { id, title, width, height, loopMs, attrs, stage, markup, values };
export default card;
